<?php

namespace Irios\WooCommerce;

/**
 * The product webhooks to the IRIOS Media sync service, set up by the plugin with nothing for the store to configure.
 *
 * - URL: https://<IRIOS Media domain>/v1/webhooks/woocommerce/<Store ID>, from the General settings. The IRIOS Media
 *   domain routes /v1/webhooks/ to the sync service, which finds the store by its Store ID.
 * - Secret: generated by the plugin the first time and kept in its own option. WooCommerce signs every delivery with
 *   it. The sync service reads it through GET /wp-json/irios/v1/sync, with the same read-only REST API key it already
 *   uses for orders and customers, so it never travels anywhere else.
 * - Webhooks: one per topic (product created, updated and deleted; "updated" also carries the stock changes, see
 *   Stock), named "IRIOS Media sync service: <topic>", which is how the plugin finds its own and never touches the
 *   store's other webhooks.
 *
 * They are kept as they should be (maintain()) when the settings are saved, when the plugin is updated, and every hour:
 * created if missing, with the current URL and secret, and turned back on if WooCommerce disabled them after failed
 * deliveries. Without IRIOS Media enabled, the domain or the Store ID, they are removed.
 */
final class SyncWebhooks {

	public const TOPICS      = array( 'product.created', 'product.updated', 'product.deleted' );
	public const NAME_PREFIX = 'IRIOS Media sync service: ';
	public const CRON_HOOK   = 'irios_wc_sync_webhooks';
	/** Generated secret (not in the settings: those are shown on the settings page and partly reach the browser). */
	public const SECRET_OPTION = 'irios_wc_sync_secret';
	/** URL the webhooks were last set up with and plugin version, to set them up again when either changes. */
	private const STATE_OPTION = 'irios_wc_sync_webhooks_state';

	public static function register(): void {
		add_action( self::CRON_HOOK, array( self::class, 'maintain' ) );
		if ( false === wp_next_scheduled( self::CRON_HOOK ) ) {
			wp_schedule_event( time() + MINUTE_IN_SECONDS, 'hourly', self::CRON_HOOK );
		}
		add_action( 'admin_init', array( self::class, 'maintain_if_changed' ) );
		add_action( 'rest_api_init', array( self::class, 'routes' ) );
	}

	/**
	 * Delivery URL, or empty when the webhooks must not exist (IRIOS Media disabled, no domain or no Store ID). The
	 * `irios_woocommerce_sync_webhook_url` filter changes it, for example in a local test store.
	 */
	public static function url( Settings $settings ): string {
		$url = $settings->enabled() && '' !== $settings->js_domain() && null !== $settings->store_id()
			? 'https://' . $settings->js_domain() . '/v1/webhooks/woocommerce/' . $settings->store_id()
			: '';
		return (string) apply_filters( 'irios_woocommerce_sync_webhook_url', $url, $settings );
	}

	/** The secret WooCommerce signs the deliveries with; generated and stored the first time. */
	public static function secret(): string {
		$secret = (string) get_option( self::SECRET_OPTION, '' );
		if ( strlen( $secret ) < 32 ) {
			$secret = bin2hex( random_bytes( 24 ) );
			update_option( self::SECRET_OPTION, $secret, false );
		}
		return $secret;
	}

	/** Creates, updates or removes the webhooks as the settings say. */
	public static function maintain(): void {
		$settings = Settings::load();
		$url      = self::url( $settings );
		self::sync( $url, '' === $url ? '' : self::secret(), self::user_id() );
		update_option( self::STATE_OPTION, $url . '|' . IRIOS_WC_VERSION, false );
	}

	/** On admin pages: only when the URL or the plugin version changed since the last set up (cheap otherwise). */
	public static function maintain_if_changed(): void {
		$state = self::url( Settings::load() ) . '|' . IRIOS_WC_VERSION;
		if ( get_option( self::STATE_OPTION ) !== $state ) {
			self::maintain();
		}
	}

	/**
	 * Creates, updates or removes the webhooks.
	 *
	 * @param string $url     Delivery URL; empty removes the webhooks.
	 * @param string $secret  Secret WooCommerce signs each delivery with.
	 * @param int    $user_id User the deliveries are built as.
	 */
	public static function sync( string $url, string $secret, int $user_id ): void {
		$existing = self::existing();
		if ( '' === $url ) {
			foreach ( $existing as $webhook ) {
				$webhook->delete( true );
			}
			return;
		}
		foreach ( self::TOPICS as $topic ) {
			$webhook = $existing[ $topic ] ?? new \WC_Webhook();
			$webhook->set_name( self::NAME_PREFIX . $topic );
			$webhook->set_topic( $topic );
			$webhook->set_delivery_url( $url );
			$webhook->set_secret( $secret );
			$webhook->set_api_version( 'wp_api_v3' );
			$webhook->set_status( 'active' );
			if ( ! $webhook->get_user_id() ) {
				$webhook->set_user_id( $user_id );
			}
			$webhook->save();
		}
	}

	/**
	 * The plugin's webhooks, by topic. A second one with the same topic (created by hand with the same name, or left
	 * by an interrupted save) is removed: two would send every change twice.
	 *
	 * @return array<string,\WC_Webhook>
	 */
	public static function existing(): array {
		$found = array();
		foreach ( self::webhook_ids() as $id ) {
			$webhook = wc_get_webhook( (int) $id );
			if ( ! $webhook instanceof \WC_Webhook || 0 !== strpos( (string) $webhook->get_name(), self::NAME_PREFIX ) ) {
				continue;
			}
			$topic = (string) $webhook->get_topic();
			if ( isset( $found[ $topic ] ) || ! in_array( $topic, self::TOPICS, true ) ) {
				$webhook->delete( true );
				continue;
			}
			$found[ $topic ] = $webhook;
		}
		return $found;
	}

	/** @return array<string,string> Status of each topic's webhook (active, disabled, paused or missing). */
	public static function statuses(): array {
		$existing = self::existing();
		$statuses = array();
		foreach ( self::TOPICS as $topic ) {
			$statuses[ $topic ] = isset( $existing[ $topic ] ) ? (string) $existing[ $topic ]->get_status() : 'missing';
		}
		return $statuses;
	}

	/** One line for the settings page. */
	public static function status( Settings $settings ): string {
		if ( '' === self::url( $settings ) ) {
			return 'Product webhooks to the IRIOS Media sync service: set up as soon as IRIOS Media is enabled with its domain and Store ID.';
		}
		$broken = array_filter( self::statuses(), static fn ( string $status ): bool => 'active' !== $status );
		if ( array() === $broken ) {
			return 'Product webhooks to the IRIOS Media sync service: active.';
		}
		$list = array();
		foreach ( $broken as $topic => $status ) {
			$list[] = $topic . ' (' . $status . ')';
		}
		return 'Product webhooks to the IRIOS Media sync service not working: ' . implode( ', ', $list ) . '. They are set up again within the hour, or when these settings are saved.';
	}

	public static function routes(): void {
		register_rest_route(
			Feed::NAMESPACE,
			'/sync',
			array(
				'methods'             => 'GET',
				'callback'            => array( self::class, 'response' ),
				'permission_callback' => array( Feed::class, 'allowed' ),
			)
		);
	}

	/** GET /wp-json/irios/v1/sync: what the sync service needs to receive and check the webhooks. */
	public static function response(): \WP_REST_Response {
		$url = self::url( Settings::load() );
		return new \WP_REST_Response(
			array(
				'webhook_url'    => '' === $url ? null : $url,
				'webhook_secret' => '' === $url ? null : self::secret(),
				'webhooks'       => (object) ( '' === $url ? array() : self::statuses() ),
			)
		);
	}

	/** Removes the plugin's webhooks, its secret and its hourly check (uninstall). */
	public static function remove(): void {
		foreach ( self::existing() as $webhook ) {
			$webhook->delete( true );
		}
		wp_clear_scheduled_hook( self::CRON_HOOK );
		delete_option( self::SECRET_OPTION );
		delete_option( self::STATE_OPTION );
	}

	/** The administrator saving the settings or, from the hourly check, the first shop manager or administrator. */
	private static function user_id(): int {
		if ( current_user_can( 'manage_woocommerce' ) ) {
			return get_current_user_id();
		}
		$users = get_users(
			array(
				'role__in' => array( 'administrator', 'shop_manager' ),
				'number'   => 1,
				'orderby'  => 'ID',
				'fields'   => 'ID',
			)
		);
		return (int) ( $users[0] ?? 0 );
	}

	/** @return int[] */
	private static function webhook_ids(): array {
		if ( ! class_exists( '\WC_Data_Store' ) ) {
			return array();
		}
		$ids = \WC_Data_Store::load( 'webhook' )->search_webhooks( array( 'limit' => -1 ) );
		return is_array( $ids ) ? array_map( 'intval', $ids ) : array();
	}
}
